import React from "react";
import { createRoot } from "react-dom/client";
import { BrowserRouter } from "react-router-dom";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { AuthContext } from "../../src/context/AuthContext";
import { FanToastProvider } from "../../src/components/fanWeb/shared/FanToast";
import GiftThanksNotice from "../../src/components/fanWeb/shared/GiftThanksNotice";
import { GIFT_THANKS_OPEN_EVENT } from "../../src/components/fanWeb/shared/giftThanksEvent";
import "../../src/index.css";
const client = new QueryClient();
createRoot(document.getElementById("root")).render(<AuthContext.Provider value={{ user: { id: "viewer" } }}><QueryClientProvider client={client}><BrowserRouter><FanToastProvider><div className="social-center-scroll" style={{ width: "min(100%,550px)", margin: "auto", minHeight: "100vh" }}><p>Profile</p><button onClick={() => window.dispatchEvent(new CustomEvent(GIFT_THANKS_OPEN_EVENT, { detail: { id: "old-thanks", preview: "Thank you for your gift", relatedCreator: { name: "Aisha", username: "aisha" } } }))}>Open saved thanks</button><GiftThanksNotice /></div></FanToastProvider></BrowserRouter></QueryClientProvider></AuthContext.Provider>);
